function estimateSqlPanelHeight(sql: string): number {
	const lineCount = Math.max(1, sql.split('\n').length);
	const lineHeight = 19;
	const editorPadding = 32;
	return lineCount * lineHeight + editorPadding + SQL_CONTENT_PADDING;
}

